INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5aed9a35-b952-58b4-a563-4d601e8bcd10'::uuid, '8ffcddff-f723-5a25-8761-11bc3c236e26'::uuid, 'Travaux d’étanchéité – ALF Sahel', 'Décapage et nettoyage des surfaces. Application d’une couche d’imprégnation à chaud. Réalisation d’une étanchéité bicouche granulée (3 et 4 mm). Mise en place d’une isolation thermique type Topox. Protection mécanique en béton. Travaux d’étanchéité des joints de dilatation. Application d’une étanchéité liquide à l’intérieur des silos.', '["https://lechantier.ma/uploads/media/8a156a5e5d5d.webp", "https://lechantier.ma/uploads/media/32e6f8978a80.webp", "https://lechantier.ma/uploads/media/ad55cda610ce.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/8a156a5e5d5d.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.7' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('dc62161d-10d6-53c8-a7e8-47e730e2270b'::uuid, '8ffcddff-f723-5a25-8761-11bc3c236e26'::uuid, 'Travaux de réalisation des délesteurs', 'Réalisation de forme de pente et chape de lissage. Application d’une couche d’imprégnation à froid type Afrikote. Mise en place d’un écran pare-vapeur 20 VV 60 F/F. Exécution d’une isolation thermique et d’une étanchéité bicouche 20 VV 60 F/F et 30 PY 180, avec relevés en 40 PY 180 ARD/F.', '["https://lechantier.ma/uploads/media/f36057f3abb5.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/f36057f3abb5.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.7' LIMIT 1));
