INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a1ab50af-5c32-5a27-b384-ba6c811a2081'::uuid, 'b144840e-c78e-563e-8b06-265742189285'::uuid, 'Installation de système de vidéosurveillance CCTV', 'Installation complète d’un système de vidéosurveillance CCTV pour la protection des habitations, commerces et bureaux. Services réalisés : Installation de caméras intérieures et extérieures. Configuration de l’enregistreur (DVR/NVR). Connexion à distance via smartphone. Intégration avec les systèmes d’alarme et de sécurité. Garantie d’une surveillance fiable 24h/24.', '["https://lechantier.ma/uploads/media/c2b6c793a336.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/c2b6c793a336.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('f3e6dea5-05ad-5883-9eaf-7d603b57d2fa'::uuid, 'b144840e-c78e-563e-8b06-265742189285'::uuid, 'isola blu caffe', 'تم بحمد الله إنجاز جميع أعمال الكهرباء في هذا المقهى باحترافية، من تركيب اللوحة الكهربائية إلى توزيع الإنارة والمقابس بطريقة آمنة ومنظمة لضمان تشغيل جميع الأجهزة بكفاءة. نحرص دائماً على الجودة، السلامة، والتنظيم في العمل باش يكون الزبون مرتاح و الخدمة تدوم لسنوات بدون مشاكل. 🔌 جميع خدمات الكهرباء المنزلية والتجارية ⚡تركيب وصيانة اللوحات الكهربائي', '["https://lechantier.ma/uploads/media/647d6d09f3bf.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/647d6d09f3bf.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
